INSERT INTO feature VALUES('toolchain-proxy','tooling','Installed toolchains and the exec proxy','driver','implemented','ordinary',NULL,'`gandr toolchain link <name> <path>` makes a build a toolchain under the user''s data directory, the first linked the default, and `gandr toolchain default` and `list` choose and show them; before any verb the driver selects one by `GANDR_TOOLCHAIN`, then the nearest `gandr-toolchain` pin, then the default, and execs its `gandr` in its own place with the same arguments, a name no installed toolchain answers refused before any verb runs. A build cargo runs from its own package, as `cargo run` and `cargo test` do, and a build run from a cargo profile directory no toolchain links run themselves and follow no switch, so a gate or a probe in a worktree judges that worktree''s driver. The nearest manifest, `package.gandr.toml` before `workspace.gandr.toml` in each directory, holds the selection to its `[toolchain]` constraint: a toolchain named outright that leaves it unmet is refused by its source, and otherwise the default runs when it meets it, else the installed toolchain of the highest version that does, each described by its own `gandr toolchain describe` once per image; none meeting it is refused with each clause the nearest leaves unmet.','surface-driver surface-dispatcher','crates/surface-driver/tests/cli.rs crates/surface-dispatcher/src/package/toolchain.rs',NULL,'#4377');
